import Foundation
import InstantCore

enum ConnectionCopyKey: String, CaseIterable {
    case intro, missing, configure, ready, openSettings, preserved, checkFields
    case checkNetwork, later, checkAccount, shorten, rephrase
    case invalidURL, invalidKey, invalidModel, keychain, keychainSave
    case authentication, permission, model, endpoint, quota, rateLimited, unavailable
    case contextLimit, rejected, offline, network, timeout, certificate, empty, format
    case interrupted, filtered, outputLimit, unknown, continueAnswer
}

struct ConnectionCopy {
    let language: Language
    static var translatedLanguages: Set<String> { Set(rows.keys) }
    static func entryCount(for language: String) -> Int { rows[language]?.components(separatedBy: "|").count ?? 0 }
    subscript(_ key: ConnectionCopyKey) -> String {
        let values = (Self.rows[language.id] ?? Self.rows["en"]!).components(separatedBy: "|")
        let index = ConnectionCopyKey.allCases.firstIndex(of: key)!
        guard values.indices.contains(index) else { return Self.rows["en"]!.components(separatedBy: "|")[index] }
        return values[index]
    }

