extension L10n {
    var connectionCopy: ConnectionCopy { ConnectionCopy(language: language) }
    private var connectionSettingsLink: String { "[\(connectionCopy[.openSettings])](instant://settings)" }
    private func connectionFields(_ fields: [ConnectionField]) -> String {
        let labels = fields.map { field in
            switch field {
            case .baseURL: return "Base URL"
            case .apiKey: return "API Key"
            case .model: return self["model"]
            }
        }
        let formatter = ListFormatter()
        formatter.locale = Locale(identifier: language.id)
        return formatter.string(from: labels) ?? labels.joined(separator: ", ")
    }
    func connectionGuidance(_ issue: ConnectionIssue) -> String {
        let copy = connectionCopy
        let action = copy[.configure].replacingOccurrences(of: "{settings}", with: connectionSettingsLink)
        switch issue {
        case .missing(let fields):
            let intro = fields.count == ConnectionField.allCases.count ? copy[.intro] + "\n\n" : ""
            return intro + copy[.missing].replacingOccurrences(of: "{fields}", with: connectionFields(fields)) + "\n" + action
        case .invalidURL: return copy[.invalidURL] + "\n" + action
        case .invalidKey: return copy[.invalidKey] + "\n" + action
        case .invalidModel: return copy[.invalidModel] + "\n" + action
        case .keychainUnavailable: return copy[.keychain] + "\n" + action
        }
    }
    func modelFailureGuidance(_ error: Error, hasPartialAnswer: Bool) -> String {
        if case ChatError.configuration(let issue) = error { return connectionGuidance(issue) }
        if case ChatError.invalidURL = error { return connectionGuidance(.invalidURL) }
        if case ChatError.missingKey = error { return connectionGuidance(.missing([.apiKey])) }
        let reason = ModelFailureReason.classify(error)
        let copy = connectionCopy
        var lines = [copy[ConnectionCopyKey(rawValue: reason.rawValue) ?? .unknown]]
        if hasPartialAnswer { lines.append(copy[.preserved]) }
        let fields: [ConnectionField]
        switch reason {
        case .authentication: fields = [.baseURL, .apiKey]
        case .permission: fields = [.apiKey, .model]
        case .model, .endpoint, .rejected, .format, .empty: fields = [.baseURL, .model]
        case .network, .certificate: fields = [.baseURL]
        case .unknown: fields = ConnectionField.allCases
        default: fields = []
        }
        if !fields.isEmpty { lines.append(copy[.checkFields].replacingOccurrences(of: "{fields}", with: connectionFields(fields))) }
        switch reason {
        case .offline, .network, .certificate: lines.append(copy[.checkNetwork])
        case .rateLimited, .unavailable, .timeout: lines.append(copy[.later])
        case .quota: lines.append(copy[.checkAccount])
        case .contextLimit: lines.append(copy[.shorten])
        case .outputLimit: lines.append(copy[.continueAnswer])
        case .filtered: lines.append(copy[.rephrase])
        default: break
        }
        if !fields.isEmpty { lines.append("\(connectionSettingsLink) · ⌘, · \(self["retry"])") }
        else if ![.filtered, .outputLimit, .contextLimit].contains(reason) { lines.append(self["retry"]) }
        return lines.joined(separator: "\n")
    }
}
